function operatorPlacements(digits: string, target: number): string[] {
  const n = digits.length, ops = ["", "+", "-", "*"], out: string[] = [];
  const evaluate = (e: string): number => {
    let total = 0;
    for (const term of e.match(/[+-]?[^+-]+/g)!) {
      const sign = term[0] === "-" ? -1 : 1;
      const body = term[0] === "+" || term[0] === "-" ? term.slice(1) : term;
      total += sign * body.split("*").reduce((p, x) => p * Number(x), 1);
    }
    return total;
  };
  const total = Math.pow(4, n - 1);
  for (let code = 0; code < total; code++) {
    let e = digits[0], c = code;
    for (let g = 1; g < n; g++) { e += ops[c % 4] + digits[g]; c = Math.floor(c / 4); }
    if (e.split(/[+\-*]/).some(p => p.length > 1 && p[0] === "0")) continue;
    if (evaluate(e) === target) out.push(e);
  }
  return out;
}

