class Solution:
    def operatorPlacements(self, digits: str, target: int) -> List[str]:
        import itertools, re
        out = []
        for ops in itertools.product(("", "+", "-", "*"), repeat=len(digits) - 1):
            e = digits[0] + "".join(o + d for o, d in zip(ops, digits[1:]))
            if any(len(p) > 1 and p[0] == "0" for p in re.split(r"[-+*]", e)):
                continue
            if eval(e) == target:
                out.append(e)
        return out

