function operatorPlacements(digits: string, target: number): string[] {
  const n = digits.length, out: string[] = [];
  const go = (i: number, expr: string, total: number, last: number): void => {
    if (i === n) { if (total === target) out.push(expr); return; }
    for (let j = i; j < n; j++) {
      if (j > i && digits[i] === "0") break; // no leading zeros
      const part = digits.slice(i, j + 1);
      const v = Number(part);
      if (i === 0) { go(j + 1, part, v, v); continue; }
      go(j + 1, expr + "+" + part, total + v, v);
      go(j + 1, expr + "-" + part, total - v, -v);
      go(j + 1, expr + "*" + part, total - last + last * v, last * v);
    }
  };
  go(0, "", 0, 0);
  return out;
}

